DASHBOARD_HTML="""<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI Branch Manager</title><style>body{font-family:system-ui;margin:0;background:#f6f7f9;color:#111}header{background:#0f172a;color:#fff;padding:24px}main{padding:24px;max-width:1100px;margin:auto}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}.card{background:#fff;border-radius:12px;padding:20px;box-shadow:0 1px 4px rgba(0,0,0,.08)}.card h3{margin:0 0 8px;font-size:14px;color:#64748b}.card p{margin:0;font-size:28px;font-weight:700}table{width:100%;border-collapse:collapse;background:#fff;margin-top:24px;border-radius:12px}th,td{padding:12px;border-bottom:1px solid #e5e7eb;text-align:left;font-size:14px}th{background:#f1f5f9}.badge{padding:4px 8px;border-radius:999px;font-size:12px}.booked{background:#dcfce7;color:#166534}.escalated{background:#fee2e2;color:#991b1b}.needs_human{background:#fef3c7;color:#92400e}</style></head><body><header><h1>AI Branch Manager</h1></header><main><div class="cards"><div class="card"><h3>Total leads</h3><p>__TOTAL__</p></div><div class="card"><h3>Booked</h3><p>__BOOKED__</p></div><div class="card"><h3>Booking rate</h3><p>__CONVERSION__%</p></div><div class="card"><h3>Pipeline value</h3><p>__PIPELINE__</p></div><div class="card"><h3>Escalations</h3><p>__ESCALATED__</p></div><div class="card"><h3>Needs human</h3><p>__NEEDS_HUMAN__</p></div></div><table><thead><tr><th>Lead</th><th>Phone</th><th>Service</th><th>Urgency</th><th>Status</th><th>Value</th></tr></thead><tbody>__ROWS__</tbody></table></main></body></html>"""
